public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    // Check if start and end are within bounds
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
        end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // If start equals end, we can trivially travel
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency list
    // Each node is represented by a pair (row, col)
    // We'll use a map from node to list of neighbors
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    // Initialize graph with all nodes
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            graph.put(i + "," + j, new java.util.ArrayList<>());
        }
    }

    // Add edges from paths
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length < 4) {
                continue;
            }
            int r1 = path[0], c1 = path[1], r2 = path[2], c2 = path[3];
            if (r1 >= 0 && r1 < n && c1 >= 0 && c1 < n && r2 >= 0 && r2 < n && c2 >= 0 && c2 < n) {
                String node1 = r1 + "," + c1;
                String node2 = r2 + "," + c2;
                graph.get(node1).add(node2);
                graph.get(node2).add(node1);
            }
        }
    }

    // BFS to check if we can reach end from start
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.LinkedList<>();

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        for (String neighbor : graph.get(current)) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null");
    }

    // Convert to uppercase for case-insensitive comparison
    String w1 = word1.toUpperCase();
    String w2 = word2.toUpperCase();

    // Count common letters (each letter counted once per word, i.e., min frequency)
    int[] freq1 = new int[26];
    int[] freq2 = new int[26];

    for (char c : w1.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq1[c - 'A']++;
        }
    }

    for (char c : w2.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq2[c - 'A']++;
        }
    }

    int commonCount = 0;
    for (int i = 0; i < 26; i++) {
        commonCount += Math.min(freq1[i], freq2[i]);
    }

    int sumLengths = w1.length() + w2.length();

    // Handle case where sum of lengths is 0
    if (sumLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Reduce the fraction commonCount / sumLengths
    int numerator = commonCount;
    int denominator = sumLengths;

    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        return "Invalid date format";
    }

    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid date format";
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12 || day < 1 || day > 31 || year < 1) {
            return "Invalid date";
        }

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.clear();
        calendar.set(year, month - 1, day);

        int weekday = calendar.get(java.util.Calendar.DAY_OF_WEEK);
        String[] weekdays = {"", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
        String weekdayName = weekdays[weekday];

        String[] monthNames = {"", "January", "February", "March", "April", "May", "June", 
                               "July", "August", "September", "October", "November", "December"};
        String monthName = monthNames[month];

        return monthName + " " + day + ", " + year + " is a " + weekdayName;
    } catch (NumberFormatException e) {
        return "Invalid date format";
    }
}

