public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }

    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (nums[mid] == target) {
            return mid;
        }

        // Left half is sorted
        if (nums[left] <= nums[mid]) {
            // Target is in the left half
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } 
        // Right half is sorted
        else {
            // Target is in the right half
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }

    int n = arr.length;
    int removeCount = (int) (n * 0.05);

    // Sort the array
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);

    // Calculate the sum of the remaining elements
    double sum = 0.0;
    int start = removeCount;
    int end = n - removeCount;

    for (int i = start; i < end; i++) {
        sum += sorted[i];
    }

    int remainingCount = end - start;
    if (remainingCount == 0) {
        return 0.0;
    }

    return sum / remainingCount;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];

    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        remainderCount[remainder]++;
    }

    // Check remainder 0: must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // Check pairs of remainders
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) {
            // When k is even and i == k/2, remainder must be even
            if (remainderCount[i] % 2 != 0) {
                return false;
            }
        } else {
            // Remainder i must pair with remainder k-i
            if (remainderCount[i] != remainderCount[k - i]) {
                return false;
            }
        }
    }

    return true;
}

