public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // Step 1-3: Pick smallest, then next smallest, etc.
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }

        // Step 4-6: Pick largest, then next largest, etc.
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // We need to find a subset of size k (1 <= k <= n-1) such that
    // sum(subset) / k == sum / n
    // => sum(subset) * n == sum * k
    // => sum(subset) == sum * k / n
    // So sum * k must be divisible by n.

    // We can use dynamic programming.
    // Let dp[i][j] be a boolean indicating whether it is possible to pick j elements
    // from the first i elements such that their sum is some value.
    // But the sum can be large. Instead, we can use a set of possible sums for each count.

    // Alternative: use a set of possible sums for each subset size.
    // Let possibleSums[k] be a set of all possible sums of subsets of size k.

    // Since n can be up to 16 (as per typical constraints for this problem), we can use bitset or boolean array.
    // But the sum can be up to 16 * 10000 = 160000, which is manageable.

    // However, a more efficient approach is to use a set of possible sums for each k.

    // We'll use a list of sets: possibleSums[k] contains all possible sums of subsets of size k.

    // Initialize: possibleSums[0] = {0}
    // For each number, update the sets in reverse order of k.

    // But note: we need to check for k from 1 to n-1.

    // Let's use an array of sets.
    java.util.Set<Integer>[] possibleSums = new java.util.Set[n + 1];
    for (int i = 0; i <= n; i++) {
        possibleSums[i] = new java.util.HashSet<>();
    }
    possibleSums[0].add(0);

    for (int num : nums) {
        // Iterate k from n down to 1 to avoid using the same element twice
        for (int k = n; k >= 1; k--) {
            for (int s : possibleSums[k - 1]) {
                possibleSums[k].add(s + num);
            }
        }
    }

    // Now check for each k from 1 to n-1:
    // if sum * k is divisible by n, and sum * k / n is in possibleSums[k]
    for (int k = 1; k < n; k++) {
        if (sum * k % n == 0) {
            int targetSum = sum * k / n;
            if (possibleSums[k].contains(targetSum)) {
                return true;
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

