public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;

    // Initialize the first window
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }

    if (!seen[mask]) {
        seen[mask] = true;
        count++;
    }

    // Slide the window
    for (int i = k; i < s.length(); i++) {
        // Remove the leftmost bit and add the new rightmost bit
        mask = ((mask << 1) | (s.charAt(i) - '0')) & (total - 1);

        if (!seen[mask]) {
            seen[mask] = true;
            count++;
            if (count == total) {
                return true;
            }
        }
    }

    return count == total;
}

