public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // The target value to make all elements equal is the average of the array.
    // Since the array is an arithmetic progression with first term 1, last term 2*(n-1)+1 = 2n-1,
    // and common difference 2, the average is (first + last) / 2 = (1 + 2n - 1) / 2 = n.
    // So the target value is n.

    // The minimum number of operations is the sum of the absolute differences between each element and the target,
    // but since each operation moves 1 unit from one element to another, the total number of operations is half the sum of absolute differences.
    // However, we can also think of it as: for each element that is less than n, we need to add (n - arr[i]) to it,
    // and for each element that is greater than n, we need to subtract (arr[i] - n) from it.
    // The total number of operations is the sum of (n - arr[i]) for all i where arr[i] < n,
    // which is the same as the sum of (arr[i] - n) for all i where arr[i] > n.

    // Let's compute the sum of (n - arr[i]) for i where arr[i] < n.
    // arr[i] = 2*i + 1 < n  =>  2*i + 1 < n  =>  i < (n-1)/2

    // For n = 3: target = 3, arr = [1, 3, 5]
    // i=0: arr[0]=1 < 3, diff = 2
    // i=1: arr[1]=3 == 3, diff = 0
    // i=2: arr[2]=5 > 3, diff = 2
    // Sum of positive diffs (or negative diffs) = 2, so operations = 2.

    // For n = 6: target = 6, arr = [1, 3, 5, 7, 9, 11]
    // i=0: 1 < 6, diff = 5
    // i=1: 3 < 6, diff = 3
    // i=2: 5 < 6, diff = 1
    // i=3: 7 > 6, diff = 1
    // i=4: 9 > 6, diff = 3
    // i=5: 11 > 6, diff = 5
    // Sum of diffs for elements < target = 5+3+1 = 9, so operations = 9.

    // We can compute this sum directly.
    // The elements less than n are arr[0], arr[1], ..., arr[k] where k is the largest index such that 2*k+1 < n.
    // k = (n-2)/2 if n is even, or (n-1)/2 - 1 if n is odd? Let's just iterate or use a formula.

    // Actually, we can derive a closed form.
    // The number of elements less than n: 
    //   If n is odd, say n = 2m+1, then arr[m] = 2m+1 = n, so elements 0 to m-1 are less than n. Count = m.
    //   If n is even, say n = 2m, then arr[m-1] = 2(m-1)+1 = 2m-1 < 2m = n, and arr[m] = 2m+1 > n. So elements 0 to m-1 are less than n. Count = m.
    // In both cases, the count is floor(n/2).

    // The sum of (n - arr[i]) for i = 0 to floor(n/2)-1:
    //   = sum_{i=0}^{m-1} (n - (2i+1)) where m = floor(n/2)
    //   = sum_{i=0}^{m-1} (n - 1 - 2i)
    //   = m*(n-1) - 2 * sum_{i=0}^{m-1} i
    //   = m*(n-1) - 2 * (m-1)*m/2
    //   = m*(n-1) - m*(m-1)
    //   = m * (n - 1 - m + 1)
    //   = m * (n - m)

    // Let's verify:
    // n=3: m = floor(3/2) = 1, result = 1 * (3-1) = 2. Correct.
    // n=6: m = floor(6/2) = 3, result = 3 * (6-3) = 9. Correct.

    int m = n / 2;
    return m * (n - m);
}

