        int next = a + b;
        if (next > k) break;
        fibs.add(next);
        a = b;
        b = next;
    }

    // Greedy approach: pick the largest Fibonacci number <= remaining k
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (fibs.get(i) <= remaining) {
            remaining -= fibs.get(i);
            count++;
            if (remaining == 0) break;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
            int other = n / i;
            if (other != i) {
                count++;
                if (count == k) {
                    return other;
                }
            }
        }
    }
    return -1;
}

