public String getSmallestString(int n, int k) {
    if (n <= 0 || k < n || k > 26 * n) {
        return "";
    }

    char[] result = new char[n];
    // Start with all 'a's
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - n; // remaining value to distribute

    // Distribute the remaining value from right to left to keep the string lexicographically smallest
    for (int i = n - 1; i >= 0; i--) {
        if (remaining <= 0) break;

        // How much can we add to this position?
        // Current char is 'a' (value 1), max is 'z' (value 26), so we can add up to 25
        int add = Math.min(remaining, 25);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

